import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"AtomicAdd","description":"","frontmatter":{},"headers":[{"level":1,"title":"AtomicAdd","slug":"atomicadd"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/原子操作/AtomicAdd.md","filePath":"api/SIMD-API/基础API/原子操作/AtomicAdd.md"}'),l={name:"api/SIMD-API/基础API/原子操作/AtomicAdd.md"};function d(p,a,i,r,o,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="atomicadd" tabindex="-1">AtomicAdd <a class="header-anchor" href="#atomicadd" aria-label="Permalink to &quot;AtomicAdd&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>调用该接口后，可在指定GM地址上进行原子加操作。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline T AtomicAdd(__gm__ T *address, T value)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int32_t/uint32_t/float/int64_t/uint64_t</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>address</td><td>输入</td><td>输入GM的地址。</td></tr><tr><td>value</td><td>输入</td><td>标量值，支持数据类型和address指向的数据类型保持一致。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>GM地址上做原子操作前的数据。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>原子操作涉及标量计算，如果标量计算单元和搬运单元（MTE2/MTE3）在读写GM时存在数据依赖，开发者需要根据实际情况插入同步。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>更多样例请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/08_atomic_operations/scalar_atomic_operations" target="_blank" rel="noreferrer">ScalarAtomicOperations样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 传入全局数据地址，初始化dstGlobal与dstLocal</span></span>
<span class="line"><span>dstGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ T *&gt;(dstGm), dataSize);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LocalTensor&lt;T&gt; dstLocal = inQueueX.AllocTensor&lt;T&gt;();</span></span>
<span class="line"><span>int32_t value = 1;</span></span>
<span class="line"><span>int32_t a = AscendC::AtomicAdd(reinterpret_cast&lt;__gm__ int32_t *&gt;(dstGm), value);</span></span>
<span class="line"><span>// 先执行完原子操作之后才能进行搬运操作，有数据依赖</span></span>
<span class="line"><span>event_t eventIdSToMte2 = static_cast&lt;event_t&gt;(GetTPipePtr()-&gt;AllocEventID&lt;HardEvent::S_MTE2&gt;());</span></span>
<span class="line"><span>// 手动插入MTE2等待Scalar的同步</span></span>
<span class="line"><span>SetFlag&lt;HardEvent::S_MTE2&gt;(eventIdSToMte2);</span></span>
<span class="line"><span>WaitFlag&lt;HardEvent::S_MTE2&gt;(eventIdSToMte2);</span></span>
<span class="line"><span>DataCopy(dstLocal, dstGlobal, dataSize);</span></span>
<span class="line"><span>// ...</span></span></code></pre></div><p>假设上述函数在3个核上执行，核1、核2、核3依次调度，结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原GM数据dst: [1,1,1,1,1,...,1] </span></span>
<span class="line"><span>核1：</span></span>
<span class="line"><span>原子计算后GM数据dst: [2,1,1,1,1,...,1] </span></span>
<span class="line"><span>返回值 a: 1</span></span>
<span class="line"><span>核2：</span></span>
<span class="line"><span>原子计算后GM数据dst: [3,1,1,1,1,...,1] </span></span>
<span class="line"><span>返回值 a: 2</span></span>
<span class="line"><span>核3：</span></span>
<span class="line"><span>原子计算后GM数据dst: [4,1,1,1,1,...,1] </span></span>
<span class="line"><span>返回值 a: 3</span></span></code></pre></div>`,21)])])}const u=t(l,[["render",d]]);export{_ as __pageData,u as default};
